import { StrictMode } from 'react'
import ReactDOM from 'react-dom/client'
import { RouterProvider, createRouter } from '@tanstack/react-router'
import './styles.css'

// 1. Generated by the Vite plugin from the files in src/routes/*
import { routeTree } from './routeTree.gen'

// 2. Runtime: create the router from the route tree
const router = createRouter({
  routeTree,
  // Start loading a route's data when the user hovers or focuses its link
  defaultPreload: 'intent',
})

// Register the router type so `Link`, `useParams`, etc. are type-checked
declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router
  }
}

// 3. RouterProvider renders the router, starting at the root route
ReactDOM.createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <RouterProvider router={router} />
  </StrictMode>,
)
